function isPlainObject(value) {
  if (value === null || typeof value !== 'object') return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function escapeHtml(value) {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function renderSessions(sessions) {
  if (!Array.isArray(sessions)) {
    throw new TypeError('sessions must be an array');
  }

  sessions.forEach((session) => {
    if (
      !isPlainObject(session) ||
      typeof session.code !== 'string' ||
      session.code.length === 0 ||
      typeof session.title !== 'string' ||
      typeof session.speaker !== 'string' ||
      !Number.isInteger(session.startMinute) ||
      session.startMinute < 0 ||
      session.startMinute > 1439
    ) {
      throw new TypeError('invalid session');
    }
  });

  sessions.sort((a, b) =>
    a.startMinute - b.startMinute ||
    (a.code < b.code ? -1 : a.code > b.code ? 1 : 0)
  );

  const rows = sessions.map((session) => {
    const hour = String(Math.floor(session.startMinute / 60)).padStart(2, '0');
    const minute = String(session.startMinute % 60).padStart(2, '0');
    return `<li class="session" data-code="${escapeHtml(session.code)}"><strong>${escapeHtml(session.title)}</strong><span>${escapeHtml(session.speaker)}</span><time>${hour}:${minute}</time></li>`;
  });

  return `<ol class="schedule">${rows.join('')}</ol>`;
}

module.exports = renderSessions;

