'use strict';
const assert = require('node:assert');
const renderSessions = require('./solution');

assert.strictEqual(renderSessions([]), '<ol class="schedule"></ol>');

const sessions = [
  { code: 'b&"', title: 'Later <Talk>', speaker: 'A > B', startMinute: 75 },
  { code: 'z', title: '', speaker: '', startMinute: 0 },
  { code: 'a', title: 'First & Best', speaker: '"Ada"', startMinute: 75 }
];
const snapshot = sessions.map((session) => ({ ...session }));
assert.strictEqual(
  renderSessions(sessions),
  '<ol class="schedule">' +
    '<li class="session" data-code="z"><strong></strong><span></span><time>00:00</time></li>' +
    '<li class="session" data-code="a"><strong>First &amp; Best</strong><span>&quot;Ada&quot;</span><time>01:15</time></li>' +
    '<li class="session" data-code="b&amp;&quot;"><strong>Later &lt;Talk&gt;</strong><span>A &gt; B</span><time>01:15</time></li>' +
  '</ol>'
);
assert.deepStrictEqual(sessions, snapshot);

assert.strictEqual(
  renderSessions([{ code: 'late', title: 'End', speaker: 'S', startMinute: 1439 }]),
  '<ol class="schedule"><li class="session" data-code="late"><strong>End</strong><span>S</span><time>23:59</time></li></ol>'
);

const invalid = [
  null,
  {},
  'sessions',
  [null],
  [[]],
  [Object.assign(Object.create({}), { code: 'x', title: 'T', speaker: 'S', startMinute: 1 })],
  [{ code: '', title: 'T', speaker: 'S', startMinute: 1 }],
  [{ code: 1, title: 'T', speaker: 'S', startMinute: 1 }],
  [{ code: 'x', title: null, speaker: 'S', startMinute: 1 }],
  [{ code: 'x', title: 'T', speaker: null, startMinute: 1 }],
  [{ code: 'x', title: 'T', speaker: 'S', startMinute: -1 }],
  [{ code: 'x', title: 'T', speaker: 'S', startMinute: 1440 }],
  [{ code: 'x', title: 'T', speaker: 'S', startMinute: 1.5 }]
];
for (const value of invalid) assert.throws(() => renderSessions(value), TypeError);

